(function(){
  var P=window.PERSONAS,dlg,last;
  function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
  function list(t,a){a=(a||[]).filter(Boolean);return a.length?"<h4>"+t+"</h4><ul>"+a.map(function(x){return"<li>"+esc(x)+"</li>";}).join("")+"</ul>":"";}
  function para(t,s){return s?"<h4>"+t+"</h4><p>"+esc(s)+"</p>":"";}
  function lenses(a){return a&&a.length?"<h4>Draws on</h4><ul>"+a.map(function(l){return"<li>"+(l.url?'<a href="'+esc(l.url)+'" target="_blank" rel="noopener noreferrer">'+esc(l.name)+"</a>":esc(l.name))+(l.what?", "+esc(l.what):"")+"</li>";}).join("")+"</ul>":"";}
  var NOTES={
    users:"Simulated user. A generic retail template until a client fork fills it from real research. Output is a hypothesis to test, never a finding.",
    comp:"Speaks only from an evidence pack. No pack has been built yet, so this player stays silent and the council points to its case studies instead.",
    sme:"A retail archetype, never a real person, and not yet checked by a practitioner. It draws on the public work of the people listed, who are lenses and are never quoted.",
    leaders:"A reasoning lens based on public work. Never quoted, and not involved.",
    tech:"A reasoning lens based on public work. Never quoted, and not involved.",
    board:"A thinking principle, not a person."
  };
  function build(){
    dlg=document.createElement("dialog");dlg.className="pdlg";dlg.setAttribute("aria-labelledby","pdlgTitle");
    dlg.innerHTML='<div class="pdlg-side"><p class="pdlg-panel" id="pdlgPanel"></p><div class="pdlg-list" role="listbox" aria-label="Personas" id="pdlgList"></div></div><div class="pdlg-main"><button type="button" class="pdlg-x" aria-label="Close">×</button><div id="pdlgBody"></div></div>';
    document.body.appendChild(dlg);
    dlg.querySelector(".pdlg-x").addEventListener("click",function(){dlg.close();});
    dlg.addEventListener("click",function(e){if(e.target===dlg)dlg.close();});
    dlg.addEventListener("close",function(){if(last)last.focus();});
  }
  function show(pid,i){
    var g=P[pid],p=g.people[i];
    dlg.style.setProperty("--c",g.color);
    document.getElementById("pdlgPanel").textContent=g.label+" ("+g.people.length+")";
    var L=document.getElementById("pdlgList");
    L.innerHTML=g.people.map(function(x,j){return '<button type="button" role="option" aria-selected="'+(j===i)+'" data-i="'+j+'">'+esc(x.name)+(x.track?'<small>'+esc(x.track)+'</small>':(x.region?'<small>'+esc(x.region)+'</small>':''))+'</button>';}).join("");
    [].forEach.call(L.querySelectorAll("button"),function(b){b.addEventListener("click",function(){show(pid,+b.dataset.i);});});
    var tmpl=/template/i.test(p.status)?'<p class="pdlg-tmpl">Template. The role detail is still to be filled from real knowledge of the role in a client fork.</p>':'';
    document.getElementById("pdlgBody").innerHTML=
      '<p class="pdlg-status"><span>'+esc(p.status)+'</span>'+(p.track?' '+esc(p.track):'')+'</p>'+
      '<h3 id="pdlgTitle">'+esc(p.name)+'</h3>'+
      (p.summary?'<p class="pdlg-sum">'+esc(p.summary)+'</p>':'')+
      '<p class="pdlg-sim">'+NOTES[pid]+'</p>'+tmpl+
      para("Known for",p.known)+para("Why it is on the council",p.why)+para("Benchmark for",p.bench)+para("What it tests",p.tests)+
      list("Experience",p.base)+lenses(p.lenses)+list("Mental models",p.models)+
      list("Cares about",p.optimizes)+list("Asks",p.asks)+
      para("Where this experience does not transfer",p.transfer)+
      para("Blind spot",p.blind)+list("Pushes back on",p.push)+para("Voice",p.voice)+
      (p.cases?para("Case studies that mention it",p.cases):'')+
      '<p class="pdlg-file">Persona file: <code>'+esc(p.file)+'</code></p>';
    var cur=L.querySelector('[aria-selected="true"]');if(cur&&cur.scrollIntoView)cur.scrollIntoView({block:"nearest"});
    document.querySelector(".pdlg-main").scrollTop=0;
  }
  document.addEventListener("click",function(e){
    var b=e.target.closest("[data-persona]");if(!b)return;
    e.preventDefault();if(!dlg)build();last=b;
    var v=b.dataset.persona.split(":");show(v[0],+(v[1]||0));
    if(!dlg.open)dlg.showModal();dlg.querySelector(".pdlg-x").focus();
  });
})();
